def _stage1_source_hashes(workspace: Path) -> dict[str, str]:
    try:
        return {
            path.relative_to(workspace).as_posix(): (
                pipeline_contract.sha256_file(path)
            )
            for path in pipeline_contract._walk_regular_files(
                workspace, "Stage 1 source workspace"
            )
        }
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def _generation_producer_sources(
    repo: Path, generator_manifest: dict[str, Any]
) -> tuple[Path, str]:
    provenance = generator_manifest.get("provenance")
    image_id = (
        provenance.get("generator_image_id")
        if isinstance(provenance, dict)
        else None
    )
    if not isinstance(image_id, str) or not image_id.startswith("sha256:"):
        raise KleanAuditContractError(
            "generator image ID is missing from Stage 4 provenance"
        )
    image_key = image_id.removeprefix("sha256:")
    try:
        image_key = pipeline_contract.validate_safe_component(
            image_key, "generator image ID"
        )
        bundle = pipeline_contract._require_direct_directory(
            repo / "data/stage4-producer-sources",
            image_key,
            "Stage 4 producer source bundle",
        )
        source_manifest = pipeline_contract._read_regular_json(
            bundle / "source-manifest.json",
            "Stage 4 producer source manifest",
        )
        expected_files = {
            "klean_export.py": generator_manifest.get("exporter_sha256"),
            "klean.py": generator_manifest.get("klean_py_sha256"),
        }
        if (
            set(source_manifest) != {
                "schema_version",
                "generator_image_id",
                "files",
            }
            or source_manifest.get("schema_version") != 1
            or source_manifest.get("generator_image_id") != image_id
            or source_manifest.get("files") != expected_files
        ):
            raise KleanAuditContractError(
                "Stage 4 producer source manifest differs from generator "
                "provenance"
            )
        observed_names = {
            path.relative_to(bundle).as_posix()
            for path in pipeline_contract._walk_regular_files(
                bundle, "Stage 4 producer source bundle"
            )
        }
        if observed_names != {
            "source-manifest.json",
            "klean_export.py",
            "klean.py",
        }:
            raise KleanAuditContractError(
                "Stage 4 producer source bundle has unexpected files"
            )
        for name, expected in expected_files.items():
            digest = _validate_sha256(
                expected, f"Stage 4 producer source {name} SHA-256"
            )
            source = pipeline_contract.require_regular_file(
                bundle / name, f"Stage 4 producer source {name}"
            )
            if pipeline_contract.sha256_file(source) != digest:
                raise KleanAuditContractError(
                    f"Stage 4 producer source {name} SHA-256 differs "
                    "from generator provenance"
                )
        return bundle, pipeline_contract.sha256_tree(bundle)
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def resolve_stage6_audit(
    repo: Path, run_id: str, problem: str
) -> dict[str, Any]:
    """Resolve and re-hash every frozen input to the Stage 6 audit."""

    try:
        task, _state, run = pipeline_contract._resolve_task_state(
            repo, run_id, problem
        )
        pipeline_contract.require_task_unblocked(task, "Stage 6")
        k_stage = pipeline_contract.require_real_directory(
            task / "01-k-proof", "Stage 1"
        )
        k_workspace = pipeline_contract.require_real_directory(
            k_stage / "workspace", "Stage 1 K workspace"
        )
        k_result = pipeline_contract._read_regular_json(
            k_stage / "result.json", "Stage 1 result"
        )
        if k_result.get("status") != "SUCCEEDED":
            raise KleanAuditContractError("Stage 1 is not successful")
        k_hash = pipeline_contract.sha256_tree(k_workspace)
        if (
            not isinstance(k_result.get("outputs"), dict)
            or k_result["outputs"].get("workspace_sha256") != k_hash
        ):
            raise KleanAuditContractError(
                "Stage 1 K workspace changed after success"
            )
        stage1_export_hash = klean_export.tree_digest(k_workspace)
        stage1_source_hashes = _stage1_source_hashes(k_workspace)

        k_audit, k_audit_selection = _selected(
            task, "02-k-audit", "executions"
        )
        k_verdict = pipeline_contract._read_regular_json(
            k_audit / "verdict.json", "Stage 2 verdict"
        )
        if (
            k_verdict.get("audit_status") != "COMPLETE"
            or k_verdict.get("legitimacy") != "LEGIT"
            or k_verdict.get("verdict") not in {"PASS", "CONCERNS"}
        ):
            raise KleanAuditContractError(
                "Stage 2 must have a selected LEGIT verdict"
            )

        try:
            discovery = stage4_runner._protected_stage3_discovery(task)
        except stage4_runner.Stage4RunnerError as error:
            raise KleanAuditContractError(str(error)) from error

        generation, generation_selection = _selected(
            task, "04-klean-generation", "generations"
        )
        generation_status = generation_selection.get("status")
        if generation_status not in {
            "PASS",
            "KLEAN_NO_OBLIGATIONS",
        }:
            raise KleanAuditContractError(
                "Stage 4 must have a selected passing Klean generation"
            )
        preflight = pipeline_contract._read_regular_json(
            generation / "preflight.json", "Stage 4 preflight"
        )
        if preflight.get("status") != generation_status:
            raise KleanAuditContractError(
                "Stage 4 selection status differs from its preflight"
            )
        generator_manifest = pipeline_contract._read_regular_json(
            generation / "generator-manifest.json", "generator manifest"
        )
        generation_producer_sources, producer_sources_hash = (
            _generation_producer_sources(repo, generator_manifest)
        )
        generated = pipeline_contract.require_real_directory(
            generation / "generated", "generated Klean project"
        )
        generated_hash = klean_export.tree_digest(generated)
        if generator_manifest.get("generated_tree_sha256") != generated_hash:
            raise KleanAuditContractError(
                "selected Stage 4 generation changed after preflight"
            )
        provenance = generator_manifest.get("provenance")
        if (
            not isinstance(provenance, dict)
            or provenance.get("stage1_workspace_sha256")
            != stage1_export_hash
            or provenance.get("stage3_discovery_manifest_sha256")
            != discovery.sha256
        ):
            raise KleanAuditContractError(
                "selected Stage 4 generation provenance is invalid"
            )
        target = generator_manifest.get("target")
        if generation_status == "PASS" and not isinstance(target, dict):
            raise KleanAuditContractError(
                "Stage 4 target manifest is malformed"
            )
        if (
            generation_status == "KLEAN_NO_OBLIGATIONS"
            and target is not None
        ):
            raise KleanAuditContractError(
                "no-obligation Stage 4 generation has an unexpected target"
            )

        lean_workspace: Path | None = None
        lean_invocation: Path | None = None
        lean_result: dict[str, Any] | None = None
        if generation_status == "PASS":
            mode = "CLASSIFICATION_AND_PROOF"
            lean_workspace, lean_invocation, lean_result = (
                _require_stage5(task)
            )
        else:
            mode = "CLASSIFICATION_ONLY"
            stage5_result = task / "05-lean-proof/result.json"
            if stage5_result.exists() or stage5_result.is_symlink():
                raise KleanAuditContractError(
                    "KLEAN_NO_OBLIGATIONS must not have a Stage 5 result"
                )
        condition = run.get("condition")
        if not isinstance(condition, dict):
            raise KleanAuditContractError("run condition is malformed")
        resolved = {
            "schema_version": stage6_resolution_contract.SCHEMA_VERSION,
            "run_id": run_id,
            "problem_id": problem,
            "condition": condition.get("name"),
            "mode": mode,
            "semantics_mode": (
                "SUPPLIED_SEMANTICS"
                if condition.get("semantics") is True
                else "GENERATED_SEMANTICS"
            ),
            "k_workspace": str(k_workspace),
            "k_audit": str(k_audit),
            "discovery_manifest": str(discovery.path),
            "klean_generation": str(generation),
            "generation_producer_sources": str(
                generation_producer_sources
            ),
            "lean_workspace": (
                str(lean_workspace)
                if lean_workspace is not None
                else None
            ),
            "lean_invocation": (
                str(lean_invocation)
                if lean_invocation is not None
                else None
            ),
            "target": target,
            "stage1_source_hashes": stage1_source_hashes,
            "trust_inventory": str(
                pipeline_contract.require_regular_file(
                    generation / "trust-inventory.json",
                    "Stage 4 trust inventory",
                )
            ),
            "hashes": {
                "k_workspace_sha256": k_hash,
                "stage1_export_sha256": stage1_export_hash,
                "discovery_manifest_sha256": discovery.sha256,
                "k_audit_sha256": pipeline_contract.sha256_tree(k_audit),
                "klean_generation_sha256": pipeline_contract.sha256_tree(
                    generation
                ),
                "generation_producer_sources_sha256": (
                    producer_sources_hash
                ),
                "generated_tree_sha256": generated_hash,
                "lean_workspace_sha256": (
                    pipeline_contract.sha256_tree(lean_workspace)
                    if lean_workspace is not None
                    else None
                ),
                "lean_invocation_sha256": (
                    pipeline_contract.sha256_tree(lean_invocation)
                    if lean_invocation is not None
                    else None
                ),
            },
            "selections": {
                "k_audit": k_audit_selection,
                "klean_generation": generation_selection,
            },
            "stage4_preflight": preflight,
            "stage5_result": lean_result,
        }
        return _stage6_audit_input(resolved)
    except klean_export.KleanExportError as error:
        raise KleanAuditContractError(str(error)) from error
    except pipeline_contract.PipelineContractError as error:
        raise _translate(error) from error


def _execution_directories(executions: Path) -> list[Path]:
    try:
        executions = pipeline_contract.require_real_directory(
            executions, "Stage 6 executions"
        )
    if export_result.get("schema_version") != 3:
        raise KleanPreflightError("export result schema version is not 3")
    if export_status not in {"OK", "KLEAN_NO_OBLIGATIONS"}:
        raise KleanPreflightError("export result status is invalid")
    input_hash = snapshot.stage1_workspace_sha256
    discovery_hash = snapshot.stage3_discovery_manifest_sha256
    generated_hash = snapshot.generated_tree_sha256
    sidecar_hashes = dict(snapshot.sidecar_sha256)
    if input_manifest.get("schema_version") != 3:
        raise KleanPreflightError("input manifest schema version is not 3")
    if generator_manifest.get("schema_version") != 3:
        raise KleanPreflightError("generator manifest schema version is not 3")
    if input_manifest.get("frozen_input_sha256") != input_hash:
        raise KleanPreflightError("frozen Stage 1 input hash changed")
    if input_manifest.get("stage1_workspace_sha256") != input_hash:
        raise KleanPreflightError("Stage 1 workspace hash changed")
    if (
        input_manifest.get("stage3_discovery_manifest_sha256")
        != discovery_hash
    ):
        raise KleanPreflightError(
            "validated Stage 3 discovery manifest hash changed"
        )
    if generator_manifest.get("generated_tree_sha256") != generated_hash:
        raise KleanPreflightError("generated project hash changed")
    if generator_manifest.get("toolchain") != lock:
        raise KleanPreflightError("generator toolchain differs from pinned lock")
    provenance = generator_manifest.get("provenance")
    if not isinstance(provenance, dict):
        raise KleanPreflightError("generator provenance is malformed")
    if provenance.get("stage1_workspace_sha256") != input_hash:
        raise KleanPreflightError(
            "Stage 1 provenance differs between generation manifests"
        )
    if provenance.get("stage3_discovery_manifest_sha256") != discovery_hash:
        raise KleanPreflightError(
            "Stage 3 provenance differs between generation manifests"
        )
    if provenance.get("inventory_sha256") != input_manifest.get(
        "inventory_sha256"
    ):
        raise KleanPreflightError(
            "Stage 1/Stage 3 inventory provenance differs"
        )
    _source_rules, obligations = _source_and_obligation_gate(
        frozen_input,
        discovery_manifest,
        generated,
        input_manifest,
        generator_manifest,
    )
    expected_export_status = "OK" if obligations else "KLEAN_NO_OBLIGATIONS"
    if export_status != expected_export_status:
        raise KleanPreflightError(
            "export status disagrees with generated obligation count"
        )
    if export_result.get("obligation_count") != len(obligations):
        raise KleanPreflightError(
            "export result obligation_count does not match generated obligations"
        )

    try:
        target = klean_export.target_statement(generated)
    except klean_export.KleanExportError as error:
        raise KleanPreflightError(str(error)) from error
    expected_target = generator_manifest.get("target")
    if target != expected_target:
        raise KleanPreflightError("target theorem statement or location changed")
    if bool(obligations) != bool(target):
        raise KleanPreflightError(
            "target proposition and obligation inventory disagree"
        )
    sources = _lean_sources(generated)
    sorry_locations: list[str] = []
    for source in sources:
        text = source.read_text()
        for forbidden in (r"\badmit\b", r"\bunsafe\b"):
            if re.search(forbidden, text):
                raise KleanPreflightError(
                    f"forbidden Lean token in {source.relative_to(generated)}"
                )
        for match in re.finditer(r"\bsorry\b", text):
            sorry_locations.append(source.relative_to(generated).as_posix())
    if sorry_locations:
        raise KleanPreflightError("generated immutable project contains sorry")
    if inventory.get("designated_sorries") != 0 or inventory.get(
        "other_sorries"
    ) != 0:
        raise KleanPreflightError("trust inventory has unexpected proof-hole counts")

    declared = _trust_declarations(sources)
    _reject_proposition_trust(generated, sources, declared)
    allowlist = inventory.get("allowlist")
    if not isinstance(allowlist, list):
        raise KleanPreflightError("trust inventory allowlist is malformed")
    expected: dict[str, tuple[str, str]] = {}
    for entry in allowlist:
        if not isinstance(entry, dict):
            raise KleanPreflightError("trust allowlist entry is malformed")
        name = entry.get("name")
        kind = entry.get("kind")
        lean_type = entry.get("type")
        reason = entry.get("reason")
        if not all(
            isinstance(value, str) and value
            for value in (name, kind, lean_type, reason)
        ):
            raise KleanPreflightError("trust allowlist entry is incomplete")
        if name in expected:
            raise KleanPreflightError(
                f"duplicate trust allowlist entry: {name}"
            )
        expected[name] = (kind, lean_type)
    if declared != expected:
        raise KleanPreflightError(
            "generated axiom/opaque declarations differ from trust allowlist"
        )
    _check_imports(generated, sources)
    export_bindings = {
        "frozen_input_sha256": input_hash,
        "stage3_discovery_manifest_sha256": discovery_hash,
        "generated_tree_sha256": generated_hash,
        "trust_inventory_sha256": sidecar_hashes[
            "trust-inventory.json"
        ],
    }
    for field, expected_hash in export_bindings.items():
        if export_result.get(field) != expected_hash:
            label = (
                "trust inventory hash"
                if field == "trust_inventory_sha256"
                else field
            )
            raise KleanPreflightError(
                f"export result {label} does not match immutable inputs"
            )

    with tempfile.TemporaryDirectory(prefix="klean-preflight-") as temporary:
        clean = Path(temporary) / "project"
        shutil.copytree(generated, clean)
        diagnostics: list[dict[str, Any]] = []
        for command in (["lake", "clean"], ["lake", "build"]):
            code, output = run_command(command, cwd=clean, timeout=600)
            diagnostics.append(
                {
                    "command": command,
                    "exit_code": code,
                    "output_sha256": hashlib.sha256(output.encode()).hexdigest(),
                    "output_tail": output[-4000:],
                }
            )
            if code != 0:
                raise KleanPreflightError(
                    f"{' '.join(command)} failed ({code}): {output[-600:]}"
                )
    _require_unchanged_snapshot(
        snapshot, frozen_input, discovery_manifest, generation
    )
    return {
        "schema_version": 3,
        "status": "PASS" if obligations else "KLEAN_NO_OBLIGATIONS",
        "frozen_input_sha256": input_hash,
        "stage1_workspace_sha256": input_hash,
        "stage3_discovery_manifest_sha256": discovery_hash,
        "generated_tree_sha256": generated_hash,
        "target": target,
        "obligation_count": len(obligations),
        "trust_declaration_count": len(declared),
        "designated_sorry_count": 0,
        "diagnostics": diagnostics,
    }


def run_preflight(
    frozen_input: Path,
    discovery_manifest: Path,
    generation: Path,
    *,
    toolchain_lock: Path,
    run_command: Callable[..., tuple[int, str]] = _run,
) -> dict[str, Any]:
    frozen_input = Path(frozen_input)
    discovery_manifest = Path(discovery_manifest)
    generation = Path(generation)
    output = generation / "preflight.json"
    if output.exists() or output.is_symlink():
        raise KleanPreflightError(f"preflight result already exists: {output}")

    def error_document(error: KleanPreflightError) -> dict[str, Any]:
        try:
            stage1_hash = klean_export.tree_digest(frozen_input)
        except (OSError, klean_export.KleanExportError):
            stage1_hash = None
        try:
            stage3_hash = hashlib.sha256(
                discovery_manifest.read_bytes()
            ).hexdigest()
        except OSError:
            stage3_hash = None
        return {
            "schema_version": 3,
            "status": "KLEAN_PREFLIGHT_ERROR",
            "error": str(error),
            "stage1_workspace_sha256": stage1_hash,
            "stage3_discovery_manifest_sha256": stage3_hash,
        }

    publication_snapshot: PreflightSnapshot | None = None
    try:
        publication_snapshot = _preflight_snapshot(
            frozen_input, discovery_manifest, generation
        )
        document = check_generation(
            frozen_input,
            discovery_manifest,
            generation,
            toolchain_lock=toolchain_lock,
            run_command=run_command,
        )
        _require_unchanged_snapshot(
            publication_snapshot,
            frozen_input,
            discovery_manifest,
            generation,
        )
    except KleanPreflightError as error:
        document = error_document(error)
    temporary = output.with_name(f".{output.name}.tmp")
    temporary.write_text(json.dumps(document, indent=2, sort_keys=True) + "\n")
    if (
        document.get("status") in {"PASS", "KLEAN_NO_OBLIGATIONS"}
        and publication_snapshot is not None
    ):
        try:
            _require_unchanged_snapshot(
                publication_snapshot,
                frozen_input,
                discovery_manifest,
                generation,
            )
        except KleanPreflightError as error:
            document = error_document(error)
            temporary.write_text(
                json.dumps(document, indent=2, sort_keys=True) + "\n"
            )
    os.replace(temporary, output)
    return document


